1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { Composer, type AssistResult, type AttachedLogo, type CreditContext } from "./Composer";
6	import { BuildLaunch } from "./BuildLaunch";
7	import {
8	  INITIAL_BUILD,
9	  parseStreamEvent,
10	  reduceBuild,
11	  type BuildProgress,
12	  type BuildSignal,
13	} from "./build-steps";
14	
15	/** Same shape the homepage hand-off uses (lib/pending-prompt.ts) so a project
16	    started here is named the way a project started there is. Reimplemented
17	    rather than imported because that helper is not exported. */
18	function deriveName(prompt: string): string {
19	  const trimmed = prompt.trim().replace(/\s+/g, " ");
20	  return trimmed.length > 60 ? trimmed.slice(0, 57) + "…" : trimmed || "New site";
21	}
22	
23	type Phase = "compose" | "building";
24	
25	/**
26	 * WHAT HAPPENS TO A LOGO AND A PALETTE HANDED OVER BY A HELPER FLOW
27	 *
28	 * Both TemplatePickerModal and InlineWizard can return `logoDataUrl` and
29	 * `palette`. Neither may be accepted from the customer and then dropped, so:
30	 *
31	 * PALETTE reaches the build as TEXT. Both flows already write their chosen
32	 * hexes into the prompt they assemble (see the `- Palette: <id> (#a to #b)`
33	 * line in lib/wizard.ts and components/templates/intake.ts), and Composer's
34	 * withPalette() appends them to the composer's own text in the case where they
35	 * are somehow absent. So the colours are in the box, where the customer can
36	 * read and change them, and they travel in the request like any other words.
37	 *
38	 * LOGO reaches the build as the `image` field on POST /api/generate — the
39	 * same field the reference-image control used to fill, and the reason the
40	 * plumbing for it survives that control's removal. components/templates/logo.ts
41	 * and components/wizard/inline-logo.ts both emit `data:image/png;base64,…`
42	 * precisely because that is the one thing the route's regex accepts, and the
43	 * route hands it to the model on ATTEMPT 1 only. The composer says exactly that
44	 * beside the thumbnail rather than implying it is uploaded and stored.
45	 *
46	 * NOT the brand-kit route (PUT /api/projects/[id]/brand), which would compile
47	 * the logo into src/components/brand/BrandLogo.tsx and seed the palette as a
48	 * Tailwind @theme block — a stronger path. buildBrandKit() in lib/brand-kit.ts
49	 * REQUIRES a business name and refuses without one, and neither pinned result
50	 * type carries one; deriving a business name from the first 60 characters of a
51	 * brief would put "A one-page site for my barbershop with services" into the
52	 * customer's header, footer and <title> verbatim, which is the exact sentence
53	 * brandPromptFragment() promises to use unaltered. A brand kit is the right
54	 * home for these once there is a name to give it, and the prompts both flows
55	 * write already tell the model honestly that the logo is guidance rather than
56	 * an asset it can embed.
57	 */
58	export function CreateFlow({
59	  initialPrompt,
60	  templateName,
61	  credits,
62	  canTopUp,
63	}: {
64	  initialPrompt: string;
65	  templateName: string | null;
66	  credits: CreditContext;
67	  canTopUp: boolean;
68	}) {
69	  const router = useRouter();
70	  const [phase, setPhase] = useState<Phase>("compose");
71	  const [prompt, setPrompt] = useState(initialPrompt);
72	  const [startedFrom, setStartedFrom] = useState<string | null>(templateName);
73	  const [logo, setLogo] = useState<AttachedLogo | null>(null);
74	  const [submitted, setSubmitted] = useState("");
75	  const [progress, setProgress] = useState<BuildProgress>(INITIAL_BUILD);
76	  const [projectId, setProjectId] = useState<string | null>(null);
77	  const [stopping, setStopping] = useState(false);
78	  /** True only when the server REFUSED the request with a non-2xx response.
79	      Those paths (kill switch, no credits, spend cap, rate limit) all return
80	      before app/api/generate/route.ts writes a Build row or a user Message, so
81	      the project is still pristine and a retry is genuinely a first build. */
82	  const [retrySafe, setRetrySafe] = useState(false);
83	
84	  const abortRef = useRef<AbortController | null>(null);
85	  const stoppedRef = useRef(false);
86	  /** Mirrors `progress` for the async loop, which cannot read state. */
87	  const stateRef = useRef<BuildProgress>(INITIAL_BUILD);
88	
89	  const running = phase === "building" && progress.outcome === "running";
90	
91	  // Closing or reloading the tab drops the response body, which aborts the
92	  // model request server-side. Warning about it is the honest thing to do —
93	  // the alternative is someone losing a build they were watching.
94	  useEffect(() => {
95	    if (!running) return;
96	    const warn = (e: BeforeUnloadEvent) => e.preventDefault();
97	    window.addEventListener("beforeunload", warn);
98	    return () => window.removeEventListener("beforeunload", warn);
99	  }, [running]);
100	
101	  // Navigating away inside the app (a sidebar link, the back button) unmounts
102	  // this component but does NOT cancel an in-flight fetch — the build would
103	  // keep running for a screen nobody is looking at and then yank the customer
104	  // into the builder from wherever they had gone. Aborting on unmount is what
105	  // makes "leaving stops the build" a true statement rather than a hope, and
106	  // an aborted build is written FAILED with creditsCharged: 0.
107	  //
108	  // Safe on the success path: `run` clears abortRef in its finally block
109	  // before React processes the navigation router.push() schedules.
110	  useEffect(() => () => abortRef.current?.abort(), []);
111	
112	  const signal = useCallback((s: BuildSignal) => {
113	    const next = reduceBuild(stateRef.current, s);
114	    stateRef.current = next;
115	    setProgress(next);
116	    return next;
117	  }, []);
118	
119	  const run = useCallback(
120	    async (text: string, imageDataUrl: string | null, existingProjectId: string | null) => {
121	      stateRef.current = INITIAL_BUILD;
122	      setProgress(INITIAL_BUILD);
123	      setStopping(false);
124	      setRetrySafe(false);
125	      stoppedRef.current = false;
126	      setSubmitted(text);
127	      setPhase("building");
128	
129	      let id = existingProjectId;
130	
131	      // ── 1. The project ───────────────────────────────────────────────────
132	      if (id === null) {
133	        try {
134	          const res = await fetch("/api/projects", {
135	            method: "POST",
136	            headers: { "Content-Type": "application/json" },
137	            body: JSON.stringify({ name: deriveName(text) }),
138	          });
139	          const body: unknown = await res.json().catch(() => null);
140	          const created =
141	            typeof body === "object" && body !== null
142	              ? (body as { project?: { id?: unknown } }).project
143	              : undefined;
144	          if (!res.ok || typeof created?.id !== "string") {
145	            const message =
146	              typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string"
147	                ? (body as { error: string }).error
148	                : "Your project couldn't be created. Nothing was charged — try again.";
149	            signal({ kind: "failed", message });
150	            setRetrySafe(true);
151	            return;
152	          }
153	          id = created.id;
154	        } catch {
155	          signal({
156	            kind: "failed",
157	            message:
158	              "Your project couldn't be created — the request didn't reach Kodely. Nothing was charged.",
159	          });
160	          setRetrySafe(true);
161	          return;
162	        }
163	        setProjectId(id);
164	      }
165	      signal({ kind: "project-created" });
166	
167	      // ── 2. The build ─────────────────────────────────────────────────────
168	      const controller = new AbortController();
169	      abortRef.current = controller;
170	
171	      try {
172	        const res = await fetch("/api/generate", {
173	          method: "POST",
174	          headers: { "Content-Type": "application/json" },
175	          body: JSON.stringify({ projectId: id, prompt: text, image: imageDataUrl }),
176	          signal: controller.signal,
177	        });
178	
179	        if (!res.ok || !res.body) {
180	          const body: unknown = await res.json().catch(() => null);
181	          const message =
182	            typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string"
183	              ? (body as { error: string }).error
184	              : "The build couldn't be started.";
185	          // A refusal happens before anything is written or charged, so this
186	          // project is still a clean slate.
187	          setRetrySafe(true);
188	          signal({ kind: "failed", message });
189	          return;
190	        }
191	
192	        signal({ kind: "accepted" });
193	
194	        const reader = res.body.getReader();
195	        const decoder = new TextDecoder();
196	        let buffer = "";
197	        let sawTerminal = false;
198	
199	        for (;;) {
200	          const { done, value } = await reader.read();
201	          if (done) break;
202	          buffer += decoder.decode(value, { stream: true });
203	
204	          const frames = buffer.split("\n\n");
205	          buffer = frames.pop() ?? "";
206	
207	          for (const frame of frames) {
208	            if (!frame.startsWith("data: ")) continue;
209	            let raw: unknown;
210	            try {
211	              raw = JSON.parse(frame.slice(6));
212	            } catch {
213	              continue;
214	            }
215	            const event = parseStreamEvent(raw);
216	            if (event === null) continue;
217	            if (event.type === "done" || event.type === "error") sawTerminal = true;
218	            signal({ kind: "sse", event });
219	          }
220	        }
221	
222	        // The route always sends `done` or `error` unless the client went
223	        // away. A stream that ends without either IS a dropped connection —
224	        // saying "finished" here would be the exact lie this screen exists to
225	        // avoid.
226	        if (!sawTerminal) signal({ kind: "lost" });
227	
228	        if (stateRef.current.outcome === "succeeded" && id !== null) {
229	          router.push(`/projects/${id}`);
230	        }
231	      } catch {
232	        if (stoppedRef.current) signal({ kind: "stopped" });
233	        else
234	          signal({
235	            kind: "failed",
236	            message:
237	              "The connection to the build dropped. Nothing was charged — open the project to see what was written.",
238	          });
239	      } finally {
240	        abortRef.current = null;
241	        setStopping(false);
242	      }
243	    },
244	    [router, signal],
245	  );
246	
247	  function stop() {
248	    if (!running || stopping || abortRef.current === null) return;
249	    stoppedRef.current = true;
250	    setStopping(true);
251	    // A real cancel: aborting the fetch closes the response body, which fires
252	    // cancel() on the route's stream and aborts the model request. The Build
253	    // row is written FAILED with creditsCharged: 0.
254	    abortRef.current.abort();
255	  }
256	
257	  if (phase === "building") {
258	    return (
259	      <BuildLaunch
260	        progress={progress}
261	        prompt={submitted}
262	        projectId={projectId}
263	        stopping={stopping}
264	        onStop={stop}
265	        onRetry={
266	          retrySafe && progress.outcome === "failed"
267	            ? () => void run(submitted, logo?.dataUrl ?? null, projectId)
268	            : null
269	        }
270	        onEdit={() => {
271	          setPhase("compose");
272	          setProgress(INITIAL_BUILD);
273	          stateRef.current = INITIAL_BUILD;
274	        }}
275	      />
276	    );
277	  }
278	
279	  return (
280	    // Centered in the visible content area, not just at the top of a tall
281	    // scroll container — the min-height subtracts the shell's own topbar and
282	    // padding so "centered" means centered in what's actually on screen,
283	    // approximately, across the range of real viewport heights rather than
284	    // exactly on any one of them.
285	    <div className="flex min-h-[calc(100dvh-var(--topbar-h)-7rem)] items-center justify-center lg:min-h-[calc(100dvh-var(--topbar-h)-9rem)]">
286	    <Composer
287	      value={prompt}
288	      onChange={setPrompt}
289	      logo={logo}
290	      onLogoChange={setLogo}
291	      // A helper flow replaces the box's contents wholesale rather than
292	      // appending: the customer picked a template or answered the wizard
293	      // specifically to REPLACE whatever placeholder text was there, and
294	      // appending would leave both texts arguing with each other in the
295	      // request. The prompt still lands in the editable box, not the request,
296	      // so nothing is submitted without the customer having seen it.
297	      onAssist={(result: AssistResult) => {
298	        setPrompt(result.prompt);
299	        setLogo(result.logo);
300	        setStartedFrom(result.templateName);
301	      }}
302	      onSubmit={() => void run(prompt.trim(), logo?.dataUrl ?? null, projectId)}
303	      fromTemplate={startedFrom}
304	      credits={credits}
305	      canTopUp={canTopUp}
306	    />
307	    </div>
308	  );
309	}
310

1	import Anthropic from "@anthropic-ai/sdk";
2	import { tmpdir } from "node:os";
3	import { ENGINE } from "./agent";
4	import { MODELS } from "./models";
5	
6	// Auto-enhance: turn a rough one-liner into a fuller spec the user reviews and
7	// edits BEFORE any credits are spent.
8	//
9	// Two jobs, both about the same failure mode — "almost right, but not quite":
10	//   1. Beginners don't know what to describe. A one-line prompt produces a
11	//      generic page, they blame the tool, they churn.
12	//   2. Nobody should discover what was built by paying for it. The spec is
13	//      shown, editable, and entirely optional; the user can always ignore it
14	//      and build with exactly what they typed.
15	//
16	// Deliberately NOT billed and NOT recorded as a build. It costs a fraction of
17	// a cent on the cheap model (see MODELS.enhancer) and charging for it would
18	// undo the point — a preview you pay for is not a preview. lib/rate-limit.ts
19	// carries the abuse ceiling instead of the credit meter.
20	
21	/** Longer than this and there is nothing left to expand — just build it. */
22	export const MAX_PROMPT_CHARS = 2000;
23	
24	// The spec is instructions for lib/agent.ts, so its hard constraints have to
25	// be repeated here or Enhance becomes a liar: it would cheerfully promise a
26	// booking system, the builder would produce a decorative form, and the user
27	// would have paid to find that out. Everything the generator cannot do is
28	// therefore banned from the spec, not merely discouraged.
29	//
30	// The word ceiling is a product decision as much as a cost one: a spec nobody
31	// reads is worse than no spec, and this has to be reviewable in ~20 seconds.
32	export const ENHANCE_SYSTEM = `You expand a one-line website idea into a short, concrete brief that the person can read, edit, and hand straight back as their build prompt.
33	
34	## What actually gets built
35	A single-page site: layout, sections, copy and visual style. That is the whole product. There is no backend of any kind.
36	
37	NEVER describe, promise or imply any of the following. The generator cannot build them, and a brief that asks for them produces a site that is broken or dishonest:
38	- databases, saved records, stored submissions, search over real data
39	- user accounts, sign-in, member areas, dashboards, admin pages
40	- payments, checkout, carts, or bookings that reserve anything real
41	- server code, APIs, scheduled jobs, email sending, contact forms that deliver a message
42	- anything loaded from another site: CDN scripts, web fonts, remote images, stock photography, embedded maps, video embeds, analytics, social feeds, live prices
43	
44	Published sites run under a strict Content Security Policy that blocks every external host. A form, a "Book now" button or a price table can exist as a VISUAL element on the page — describe it that way, and never as something that works.
45	
46	Images are inline SVG, CSS gradients and shapes, or simple illustration. Type comes from the system font stack. Say so when it matters; do not ask for photographs or a specific web font.
47	
48	## What to write
49	Plain text. No code, no markdown fences, no bullet characters beyond simple dashes. Under 220 words. Write in the same language the person used. Use exactly these five headings, in this order:
50	
51	Audience — who the site is for, in one sentence.
52	Goal — the single thing a visitor should do or understand.
53	Tone and visual style — two or three concrete adjectives, plus the colour feel, the typographic feel, and how imagery is handled.
54	Sections — the page's sections in order, each with one line saying what it holds.
55	Key content — the actual headline wording, the nav and button labels, and any names or claims to use.
56	
57	Rules:
58	- Be specific. Real headline wording, real section names, real labels — never "your headline here".
59	- Invent no facts about a real business: no addresses, phone numbers, prices, opening hours, testimonials or statistics. Where one is clearly needed, write a bracketed placeholder such as [your address] for the person to fill in.
60	- Keep every choice the person already made. Expand their idea; do not replace it.
61	- Output the brief and nothing else. No preamble, no sign-off, no questions back.`;
62	
63	// The metered path's client, constructed the same way lib/agent.ts does.
64	// Harmless when KODELY_ENGINE=sdk: nothing on that path ever calls it.
65	const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
66	
67	// Hard ceilings, because the caller is a person staring at a spinner next to a
68	// button they could just press instead. The SDK path is far more generous: it
69	// spawns a Claude Code process, and cold start alone can eat several seconds.
70	const API_TIMEOUT_MS = 25_000;
71	const SDK_TIMEOUT_MS = 60_000;
72	
73	/**
74	 * One AbortSignal that trips on whichever comes first: our own deadline, or
75	 * the client hanging up. AbortSignal.any would do this in one line but the
76	 * timer still has to be cleared, so the teardown callback is needed regardless.
77	 */
78	function withDeadline(ms: number, signal?: AbortSignal) {
79	  const controller = new AbortController();
80	  const timer = setTimeout(() => controller.abort(), ms);
81	  const onAbort = () => controller.abort();
82	  if (signal?.aborted) controller.abort();
83	  else signal?.addEventListener("abort", onAbort, { once: true });
84	  return {
85	    controller,
86	    release() {
87	      clearTimeout(timer);
88	      signal?.removeEventListener("abort", onAbort);
89	    },
90	  };
91	}
92	
93	function userTurn(prompt: string): string {
94	  return `Here is the rough idea, exactly as the person typed it:\n\n${prompt}`;
95	}
96	
97	async function enhanceViaApi(prompt: string, signal?: AbortSignal): Promise<string> {
98	  const { controller, release } = withDeadline(API_TIMEOUT_MS, signal);
99	  try {
100	    // No `thinking` and no `output_config.effort` here on purpose: Haiku 4.5
101	    // rejects effort, and a 220-word brief is not a reasoning problem. If
102	    // KODELY_MODEL_ENHANCER is ever pointed at a bigger model, this stays
103	    // correct — it just leaves that model on its own defaults.
104	    const message = await anthropic.messages.create(
105	      {
106	        model: MODELS.enhancer,
107	        max_tokens: 1500,
108	        // No cache_control, unlike lib/agent.ts: this system prompt is well
109	        // under the ~1k-token minimum cacheable prefix, so a breakpoint here
110	        // would be silently ignored and only mislead the next reader.
111	        system: ENHANCE_SYSTEM,
112	        messages: [{ role: "user", content: userTurn(prompt) }],
113	      },
114	      { signal: controller.signal },
115	    );
116	
117	    if (message.stop_reason === "refusal") {
118	      throw new Error("The request was declined.");
119	    }
120	
121	    return message.content
122	      .filter((block): block is Anthropic.TextBlock => block.type === "text")
123	      .map((block) => block.text)
124	      .join("")
125	      .trim();
126	  } finally {
127	    release();
128	  }
129	}
130	
131	async function enhanceViaSdk(prompt: string, signal?: AbortSignal): Promise<string> {
132	  // Imported for its module-scope side effect as much as for query():
133	  // lib/agent-sdk.ts strips ANTHROPIC_API_KEY from the environment so nothing
134	  // the SDK spawns can quietly bill the metered key on a box whose operator
135	  // asked for the subscription engine. Enhance can be the first SDK call a
136	  // process makes, so it must not skip that.
137	  await import("./agent-sdk");
138	  const { query } = await import("@anthropic-ai/claude-agent-sdk");
139	
140	  const { controller, release } = withDeadline(SDK_TIMEOUT_MS, signal);
141	  let out = "";
142	  try {
143	    for await (const message of query({
144	      prompt: userTurn(prompt),
145	      options: {
146	        systemPrompt: ENHANCE_SYSTEM,
147	        model: MODELS.enhancer,
148	        // No tools at all — this is one prompt in, one paragraph out. Combined
149	        // with a temp cwd and no filesystem settings, the agent has nothing to
150	        // read: it cannot wander into this repo or pick up its CLAUDE.md.
151	        allowedTools: [],
152	        settingSources: [],
153	        cwd: tmpdir(),
154	        maxTurns: 1,
155	        permissionMode: "dontAsk",
156	        abortController: controller,
157	      },
158	    })) {
159	      if (message.type === "assistant" && message.message?.content) {
160	        for (const block of message.message.content) {
161	          if ("text" in block && block.text) out += block.text;
162	        }
163	      }
164	    }
165	  } finally {
166	    release();
167	  }
168	
169	  if (controller.signal.aborted) throw new Error("Enhance timed out.");
170	  return out.trim();
171	}
172	
173	/**
174	 * Expand `prompt` into a reviewable spec.
175	 *
176	 * Throws on timeout, disconnect, refusal, or an empty answer. Every caller is
177	 * expected to swallow that and carry on with the user's original prompt —
178	 * Enhance is a convenience, and a failed convenience must never stand between
179	 * someone and the build they came here for.
180	 */
181	export async function enhancePrompt(prompt: string, signal?: AbortSignal): Promise<string> {
182	  const spec = ENGINE === "sdk" ? await enhanceViaSdk(prompt, signal) : await enhanceViaApi(prompt, signal);
183	  if (!spec) throw new Error("The model returned an empty spec.");
184	  return spec;
185	}
186

1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { FOUNDATION_FILES } from "@/lib/foundation";
4	import { track, EVENTS } from "@/lib/events";
5	
6	export const dynamic = "force-dynamic";
7	
8	function slugify(name: string): string {
9	  const base = name
10	    .toLowerCase()
11	    .replace(/[^a-z0-9]+/g, "-")
12	    .replace(/^-+|-+$/g, "")
13	    .slice(0, 40);
14	  return (base || "site") + "-" + Math.random().toString(36).slice(2, 7);
15	}
16	
17	export async function GET() {
18	  const user = await requireUser().catch(() => null);
19	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
20	
21	  const projects = await db.project.findMany({
22	    where: { userId: user.id },
23	    orderBy: { updatedAt: "desc" },
24	    select: { id: true, name: true, slug: true, publishedAt: true, updatedAt: true, createdAt: true },
25	  });
26	  return Response.json({ projects });
27	}
28	
29	export async function POST(req: Request) {
30	  const user = await requireUser().catch(() => null);
31	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
32	
33	  const body = (await req.json().catch(() => null)) as { name?: string } | null;
34	  const name = body?.name?.trim().slice(0, 80) || "Untitled site";
35	
36	  const project = await db.project.create({
37	    data: { userId: user.id, name, slug: slugify(name) },
38	  });
39	
40	  // Every project starts from the real Vite+React+TS+Tailwind foundation,
41	  // not a blank slate — the agent edits/extends this, it never scaffolds
42	  // a project from scratch.
43	  await db.projectFile.createMany({
44	    data: Object.entries(FOUNDATION_FILES).map(([path, content]) => ({
45	      projectId: project.id,
46	      path,
47	      content,
48	      published: false,
49	      kind: "source",
50	    })),
51	  });
52	
53	  track(EVENTS.projectCreated, { userId: user.id, props: { projectId: project.id } });
54	
55	  return Response.json({ project });
56	}
