1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { track, EVENTS } from "@/lib/events";
4	
5	export const dynamic = "force-dynamic";
6	
7	// Same ceiling the create route applies (app/api/projects/route.ts). Kept in
8	// sync by hand rather than imported: route modules aren't a shared-constants
9	// home, and that file doesn't export it.
10	const NAME_MAX = 80;
11	
12	// Mirrors slugify() in app/api/projects/route.ts. Duplicated rather than
13	// imported for the same reason as NAME_MAX — importing across route modules
14	// couples two request entrypoints for one pure function. The random suffix is
15	// what makes collisions rare; POST below still retries on the off chance.
16	function slugify(name: string): string {
