14	export default async function ProjectPage({ params }: { params: Promise<{ id: string }> }) {
15	  const user = await getCurrentUser();
16	  if (!user) redirect("/login");
17	  const { id } = await params;
18	
19	  const project = await db.project.findFirst({
20	    where: { id, userId: user.id },
21	    include: {
22	      files: { where: { published: false, kind: "source" } },
23	      messages: { orderBy: { createdAt: "asc" } },
24	    },
25	  });
26	  if (!project) redirect("/dashboard");
27	
28	  // Only builds whose snapshot SURVIVES are checkpoints. The filter is the same
29	  // one app/api/projects/[id]/builds/route.ts applies and for the same reason
30	  // (the retention job clears filesSnapshot on old builds); duplicated rather
31	  // than imported because a route module is not a shared-query home, and the
32	  // editor refetches through that route after every build anyway, so the two
33	  // lists have to agree. `take: 100` matches it too.
34	  const CHECKPOINTS = {
35	    where: {
36	      projectId: id,
37	      status: "SUCCEEDED",
38	      filesSnapshot: { not: Prisma.DbNull },
39	    },
40	    orderBy: { createdAt: "desc" },
41	  } as const;
42	
43	  const [balance, avgBuildCredits, measuredBuilds, unreadSubmissions, checkpoints, latest] =
44	    await Promise.all([
45	      getBalance(user.id),
46	    averageBuildCredits(user.id),
47	    // averageBuildCredits() falls back to a global constant for someone with no
48	    // history, so on its own it cannot be described to the user as "your"
49	    // average. This count is the gate that decides whether it can — the same
50	    // gate app/dashboard/billing/page.tsx uses for its "Your average build" tile.
51	    db.build.count({
52	      where: { project: { userId: user.id }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
53	    }),
54	      // Same filter the submissions page uses for its own unread count, so the
55	      // badge and the page can never disagree about what "unread" means.
56	      db.formSubmission.count({ where: { projectId: id, readAt: null, spam: false } }),
57	      // The undo timeline, resolved here so the control can be labelled with
58	      // its real target on first paint instead of after a round trip.
59	      db.build.findMany({
60	        ...CHECKPOINTS,
61	        take: 100,
62	        select: { id: true, prompt: true, createdAt: true, filesWritten: true },
63	      }),
64	      // The newest checkpoint's snapshot, read ONLY to answer "does the draft
65	      // still match it". ~105 kB, the same order as the draft tree this page
66	      // already loads, and it never leaves the server — only the boolean below
67	      // is sent. The alternative was inferring it from updatedAt timestamps,
68	      // which cannot tell a manual SEO/Brand save apart from the build's own
69	      // write, and would make Undo's label a guess. Undo replaces the draft; a
70	      // guess is not good enough to describe that.
71	      db.build.findFirst({ ...CHECKPOINTS, select: { id: true, filesSnapshot: true } }),
72	    ]);
73	
74	  const draftFiles = Object.fromEntries(project.files.map((f) => [f.path, f.content]));
75	  const draftDiffersFromLatest =
76	    latest?.filesSnapshot != null &&
77	    !sameTree((latest.filesSnapshot as Snapshot).source ?? {}, draftFiles);
78	
79	  return (
80	    <Editor
81	      projectId={project.id}
82	      projectName={project.name}
83	      slug={project.slug}
84	      published={!!project.publishedAt}
85	      initialFiles={draftFiles}
86	      initialMessages={project.messages.map((m) => ({ role: m.role, content: m.content }))}
87	      initialBalance={balance}
88	      avgBuildCredits={avgBuildCredits}
89	      measuredBuilds={measuredBuilds}
90	      // Resolved here rather than in the client: lib/credits.ts reaches for
91	      // Prisma at module scope, so it can never be imported from Editor.tsx.
92	      estimates={{ create: estimateCredits("create"), edit: estimateCredits("edit") }}
93	      unreadSubmissions={unreadSubmissions}
94	      initialCheckpoints={checkpoints.map((b) => ({
95	        id: b.id,
96	        prompt: b.prompt,
97	        createdAt: b.createdAt.toISOString(),
98	        filesWritten: b.filesWritten,
99	      }))}
100	      draftDiffersFromLatest={draftDiffersFromLatest}
101	    />
102	  );
103	}
