40	export type SeoTags = {
41	  title: string;
42	  description: string;
43	  ogTitle: string;
44	  ogDescription: string;
45	  /** Read-only here: it is an asset reference, not copy. */
46	  ogImage: string;
47	};
48	
49	const EMPTY: SeoTags = { title: "", description: "", ogTitle: "", ogDescription: "", ogImage: "" };
50	
51	/**
52	 * Read the head with the browser's own HTML parser rather than regexes:
53	 * attribute order, quoting style and entities (&amp;, &#39;) are all things
54	 * the builder writes freely and all things a regex would show back to the
55	 * user raw. This runs client-side only — the panel is never server-rendered,
56	 * since it mounts only once the user switches to this view.
57	 */
58	function parseHead(html: string | undefined): SeoTags {
59	  if (!html || typeof DOMParser === "undefined") return EMPTY;
60	  const doc = new DOMParser().parseFromString(html, "text/html");
61	  const content = (selector: string) =>
62	    doc.querySelector(selector)?.getAttribute("content")?.trim() ?? "";
63	  return {
64	    title: doc.querySelector("title")?.textContent?.trim() ?? "",
65	    description: content('meta[name="description"]'),
66	    ogTitle: content('meta[property="og:title"]'),
67	    ogDescription: content('meta[property="og:description"]'),
68	    ogImage: content('meta[property="og:image"]'),
69	  };
70	}
71	
72	/**
73	 * What a visitor and a crawler actually get for a PUBLISHED site, gaps
74	 * included. Mirrors applySeo() in lib/site-seo.ts line for line.
75	 *
76	 * One rule here is easy to get wrong and is deliberately preserved: an empty
77	 * og:description does NOT inherit the page description. applySeo computes one
78	 * generic string from the title and uses it for both, so leaving og:description
79	 * blank while writing a real description gets you the generic line in every
80	 * link preview. Showing that plainly is the point of this column.
81	 */
82	function servedValues(tags: SeoTags, projectName: string) {
83	  const title =
84	    !tags.title || tags.title === PLACEHOLDER_TITLE ? projectName : tags.title;
85	  const generated = `${title} — built with Kodely.`;
86	  return {
87	    title,
88	    titleIsFallback: !tags.title || tags.title === PLACEHOLDER_TITLE,
89	    description: tags.description || generated,
90	    descriptionIsFallback: !tags.description,
91	    ogTitle: tags.ogTitle || title,
92	    ogTitleIsFallback: !tags.ogTitle,
93	    ogDescription: tags.ogDescription || generated,
94	    ogDescriptionIsFallback: !tags.ogDescription,
95	  };
96	}
