98	function sameTags(a: SeoTags, b: SeoTags): boolean {
99	  return (
100	    a.title === b.title &&
101	    a.description === b.description &&
102	    a.ogTitle === b.ogTitle &&
103	    a.ogDescription === b.ogDescription
104	  );
105	}
