129	  // round trip on every panel open whose only outcome was a claim that had
130	  // become false. A failure still surfaces, but as the error it actually is.
131	  const endpoint = `/api/projects/${projectId}/seo`;
132	  const [saving, setSaving] = useState(false);
133	  const [saveError, setSaveError] = useState<string | null>(null);
134	  const [savedAt, setSavedAt] = useState<number | null>(null);
