140	  // Adopt new file contents (a finished build, or our own save landing) only
141	  // when the user has nothing unsaved in the boxes. Silently replacing text
142	  // someone is halfway through typing is worse than showing a stale value.
143	  useEffect(() => {
144	    setDraft((d) => (sameTags(d, baseline.current) ? current : d));
145	    baseline.current = current;
146	  }, [current]);
147	
148	  const dirty = !sameTags(draft, current);
149	  const served = servedValues(draft, projectName);
