1	import { db } from "@/lib/db";
2	import { requireUser } from "@/lib/auth";
3	import { applyHead } from "./head";
4	
5	export const dynamic = "force-dynamic";
6	
7	// Edit a site's <head> metadata without paying for a generation.
8	//
9	// There is no SEO column anywhere — the head of the project's own index.html
10	// IS the storage (see lib/site-seo.ts, which only fills gaps at serve time).
11	// So this rewrites that file in place.
12	//
13	// Generous next to the ~60/~150 character guidance in lib/agent.ts's SYSTEM
14	// prompt: that guidance is about what reads well in a search result, and it is
15	// the panel's job to nudge. Refusing to save a 61-character title would be this
16	// route inventing a rule the rest of the system does not have.
17	const LIMITS = { title: 200, description: 400, ogTitle: 200, ogDescription: 400 } as const;
18	
19	function field(raw: unknown, max: number): string | null {
20	  if (typeof raw !== "string") return null;
21	  const v = raw.trim();
22	  return v.length > max ? null : v;
23	}
24	
25	export async function PUT(req: Request, { params }: { params: Promise<{ id: string }> }) {
26	  const user = await requireUser().catch(() => null);
27	  if (!user) return Response.json({ error: "Not signed in." }, { status: 401 });
28	  const { id } = await params;
29	
30	  const body = (await req.json().catch(() => null)) as Record<string, unknown> | null;
31	  if (!body) return Response.json({ error: "Invalid request." }, { status: 400 });
32	
33	  const title = field(body.title, LIMITS.title);
34	  const description = field(body.description, LIMITS.description);
35	  const ogTitle = field(body.ogTitle, LIMITS.ogTitle);
36	  const ogDescription = field(body.ogDescription, LIMITS.ogDescription);
37	  if (title === null || description === null || ogTitle === null || ogDescription === null) {
38	    return Response.json({ error: "One of those fields is too long." }, { status: 400 });
39	  }
40	
41	  // Ownership scoped in the SAME query as the id, so someone else's project id
42	  // is indistinguishable from a nonexistent one.
43	  const project = await db.project.findFirst({
44	    where: { id, userId: user.id },
45	    select: { id: true },
46	  });
47	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
48	
49	  // BOTH draft trees, and each for its own reason:
50	  //   source — or the next generation reads the old head back and the edit
51	  //            silently reverts.
52	  //   build  — or the preview and any subsequent publish keep serving the old
53	  //            tags, because publish copies the draft BUILD rows.
54	  // Deliberately NOT published:true. Going live stays an explicit publish, so
55	  // editing metadata can never push an unreviewed change to a live site.
56	  const rows = await db.projectFile.findMany({
57	    where: { projectId: id, published: false, path: "index.html" },
58	    select: { id: true, kind: true, content: true },
59	  });
60	  if (rows.length === 0) {
61	    return Response.json(
62	      { error: "This project has no index.html yet — build the site first." },
63	      { status: 400 },
64	    );
65	  }
66	
67	  const values = { title, description, ogTitle, ogDescription };
68	  const updates = rows
69	    .map((row) => ({ row, next: applyHead(row.content, values) }))
70	    .filter(({ row, next }) => next !== row.content);
71	
72	  if (updates.length > 0) {
73	    await db.$transaction(
74	      updates.map(({ row, next }) =>
75	        db.projectFile.update({ where: { id: row.id }, data: { content: next } }),
76	      ),
77	    );
78	  }
79	
80	  return Response.json({ ok: true, updated: updates.map((u) => u.row.kind) });
81	}
